/* SideScroll built-in project content.
 * project-defaults-data.js (generated by tools/bake_project.py from a Project
 * Backup export) holds the authored world, puzzles, assets and characters. When
 * code reads one of those localStorage keys and this device has no saved value,
 * it gets the built-in value instead, so a fresh install starts with the full
 * project. Saved data on the device always wins and is never written or changed
 * here; removing a key (a lab's Reset) returns it to the built-in content.
 * Saving a value identical to the built-in one, on a device with no copy of its
 * own, is skipped: the game re-saves some content on every load (migrations),
 * and storing it would pin that device to today's version so later published
 * updates would never reach it.
 * Renamed storage keys (storage-catalogue.json "renamed", copied into the
 * generated data as renamedKeys) are migrated here once per device: a value
 * saved under an old key moves to the new key, so code only uses new names.
 * Values inside saved data are then migrated (saved-data-migrations.js, which
 * loads just before this file): a device's own copies only, rewritten in place.
 * Must load before any script that reads saved data.
 */
(() => {
  'use strict';
  const defaults = window.SIDESCROLL_PROJECT_DEFAULTS?.storage;
  if (!defaults) return;
  let store = null;
  try { store = window.localStorage; } catch (_) { return; }
  if (!store) return;

  const has = Object.prototype.hasOwnProperty;
  const proto = Object.getPrototypeOf(store);
  const getItem = proto.getItem;
  const setItem = proto.setItem;
  proto.getItem = function (key) {
    const value = getItem.call(this, key);
    if (value === null && this === store && has.call(defaults, key)) return defaults[key];
    return value;
  };
  proto.setItem = function (key, value) {
    if (this === store && has.call(defaults, key) && String(value) === defaults[key]
      && getItem.call(this, key) === null) return;
    return setItem.call(this, key, value);
  };

  // One-time move of values saved under renamed keys. If the device already has
  // the new key, the old copy is simply dropped (the new one is newer).
  const renamedKeys = window.SIDESCROLL_PROJECT_DEFAULTS.renamedKeys || {};
  for (const [oldKey, newKey] of Object.entries(renamedKeys)) {
    try {
      const old = getItem.call(store, oldKey);
      if (old === null) continue;
      if (getItem.call(store, newKey) === null) store.setItem(newKey, old);
      store.removeItem(oldKey);
    } catch (_) {}
  }

  // Value-level migrations of this device's own copies (built-in data is baked
  // in the current format). Idempotent, so it simply runs on every load.
  const migrations = window.SideScrollMigrations;
  for (const key of migrations?.KEYS || []) {
    try {
      const raw = getItem.call(store, key);
      const next = migrations.migrateRaw(key, raw);
      if (next !== raw) setItem.call(store, key, next);
    } catch (_) {}
  }

  window.SideScrollProjectDefaults = Object.freeze({
    renamedKeys: Object.freeze({ ...renamedKeys }),
    exportedAt: window.SIDESCROLL_PROJECT_DEFAULTS.exportedAt || null,
    has: key => has.call(defaults, key),
    isBuiltIn: key => has.call(defaults, key) && getItem.call(store, key) === null
  });
})();
